              "broker": "한화증권",
              "analyst": "김유민",
              "date": "2026-02-13",
              "summary": "- 코인베이스의 FY 4Q25 매출은 17.8억 달러(YoY -21.6%)로 예상치를 2.7% 하회했다. 그 중 거래 매출은 9.8억 달러 규모로 전년 대비 36.8% 감소했다- 개인 고객 매출은 7.3억 달러로 전 분기 대비 13% 감소했다. Advanced Trading* 매출 비중이 높아졌고, 수수료 면제 혜 택이 있는 Coinbase One 구독자의 거래 비중이 증가하면서 매출이 줄 었다. 4분기 시장 부진으로 거래량이 감소한 점도 작용했다- 구독 및 서비스 매출은 7.3억 달러로 전년 대비 13.5% 확대됐다. 그 중 스테이블코인 매출은 3.6억 달러로 전분기 대비 2% 늘었다. 코인베 이스 플랫폼 내 USDC 보유량이 전분기 대비 18% 증가한 178억 달러 로 역대 최고치를 기록했다",
