              "summary": "- 12월 17일, 코인베이스는 Everything Exchange를 내세우며 주식 거래, 예측시장, 무기한 선물 시장 진출을 발표했다. 암호화폐 + 주식 + 예 측시장 + 파생상품 + DEX + 토큰 세일이 하나의 앱 안에서 모두 가 능해진다.- 증권은 자회사인 Coinbase Capital Markets Corp(브로커딜 러, FINRA/SIPC 회원)가 제공하고, 집행/청산/수탁은 APEX Clearing 이 담당한다- 예측시장 서비스를 지원한다. 암호화폐 가격뿐만 아니라 스포츠, 엔터 테인먼트, 선거, 정책, 경제 성과 등 다양한 이벤트에 대한 계약을 제공 한다. 예측시장 플랫폼인 칼시와의 협력을 통해 거래를 개시했다",
