            "statement": "이사 Mauad Bruno Sousa가 2026년 8월 28일 252,000주를 주당 86.48달러(총 2179만2960달러)에 매수해 직접 보유 지분이 종전 대비 152.40% 증가했다. 시점상 원 자료의 '9/2 Insider Buying Report' 기사와 일치하며 경영진의 자사 주식에 대한 강한 확신을 시사한다.",
